// Parse file paths and read content
const output = $input.first().json.stdout;
const filePaths = output.split('\n').filter(path => path.trim());

const contextFiles = [];

for (const filePath of filePaths) {
  if (filePath.includes('context/')) {
    const category = filePath.split('/')[1];
    const fileName = filePath.split('/').pop().replace('.md', '');

    contextFiles.push({
      path: filePath,
      category: category,
      name: fileName,
      type: fileName.includes('repo') ? 'repository' : 
            fileName.includes('team') ? 'team' :
            fileName.includes('project') ? 'project' : 
            fileName.includes('page') ? 'linkedin' : 'other'
    });
  }
}

return contextFiles.map(file => ({ json: file }));

// Combine file metadata with content
const fileData = $input.first().json;
const content = fileData.stdout || '';

// Extract key information
const lines = content.split('\n');
let summary = '';
let metrics = [];
let technologies = [];

// Parse content for key details
for (let i = 0; i < Math.min(lines.length, 50); i++) {
  const line = lines[i].toLowerCase();

  // Extract metrics (numbers with %)
  const metricMatch = line.match(/(\d+)%/);
  if (metricMatch) {
    metrics.push(line.trim());
  }

  // Extract technologies
  if (line.includes('tech') || line.includes('stack') || line.includes('built')) {
    technologies.push(lines[i].trim());
  }
}

// Get first meaningful paragraph as summary
const paragraphs = content.split('\n\n').filter(p => p.length > 50);
summary = paragraphs[0] || content.substring(0, 500);

return {
  json: {
    file_name: $('Parse File Paths').item.json.name,
    file_path: $('Parse File Paths').item.json.path,
    category: $('Parse File Paths').item.json.category,
    type: $('Parse File Paths').item.json.type,
    content: content,
    summary: summary,
    metrics: metrics,
    technologies: technologies,
    word_count: content.split(/\s+/).length,
    char_count: content.length
  }
};

// Parse Claude's response and extract posts
const claudeResponse = $input.first().json;
const responseText = claudeResponse.content[0].text;

// Extract JSON from response (handle both raw JSON and markdown-wrapped JSON)
let postsData;
try {
  // Try parsing as-is
  postsData = JSON.parse(responseText);
} catch (e) {
  // Try extracting from markdown code block
  const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/) || 
                    responseText.match(/```\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    postsData = JSON.parse(jsonMatch[1]);
  } else {
    throw new Error('Could not parse Claude response as JSON');
  }
}

const sourceFile = $('Process Content').item.json.file_name;
const sourceCategory = $('Process Content').item.json.category;
const sourceType = $('Process Content').item.json.type;

// Create individual items for each post variation
const posts = postsData.posts.map((post, index) => {
  // Validate quality
  const issues = [];

  if (post.word_count < 120 || post.word_count > 180) {
    issues.push('Word count outside 120-180 range');
  }

  if (post.hashtags.length !== 4) {
    issues.push('Must have exactly 4 hashtags');
  }

  // Check for buzzwords
  const fullText = `${post.hook} ${post.body} ${post.cta}`.toLowerCase();
  const buzzwords = ['revolutionary', 'game-changing', 'disruptive', 'magical', 'transform your'];
  const foundBuzzwords = buzzwords.filter(word => fullText.includes(word));

  if (foundBuzzwords.length > 0) {
    issues.push(`Contains buzzwords: ${foundBuzzwords.join(', ')}`);
  }

  // Check emoji count
  const emojiRegex = /\p{Emoji}/gu;
  const emojiCount = (fullText.match(emojiRegex) || []).length;
  if (emojiCount > 2) {
    issues.push(`Too many emojis: ${emojiCount} (max 2)`);
  }

  // Determine quality score
  let qualityScore = 100;
  qualityScore -= issues.length * 10;
  if (post.word_count >= 140 && post.word_count <= 160) qualityScore += 5;
  if (!foundBuzzwords.length) qualityScore += 10;

  let status = 'APPROVED';
  if (qualityScore < 70) status = 'NEEDS_REVISION';
  if (qualityScore < 50) status = 'REJECTED';

  return {
    json: {
      post_id: `${sourceFile.replace('/', '-')}-${post.variation}-${Date.now()}-${index}`,
      source_file: sourceFile,
      source_category: sourceCategory,
      source_type: sourceType,
      variation: post.variation,
      hook: post.hook,
      body: post.body,
      cta: post.cta,
      hashtags: post.hashtags,
      full_text: `${post.hook}\n\n${post.body}\n\n${post.cta}\n\n${post.hashtags.map(tag => '#' + tag).join(' ')}`,
      word_count: post.word_count,
      quality_score: qualityScore,
      status: status,
      issues: issues,
      generated_at: new Date().toISOString()
    }
  };
});

return posts;

