// Generate batch summary report
const allPosts = $input.all();

const approved = allPosts.filter(p => p.json.status === 'APPROVED');
const needsRevision = allPosts.filter(p => p.json.status === 'NEEDS_REVISION');
const rejected = allPosts.filter(p => p.json.status === 'REJECTED');

const avgQualityScore = allPosts.reduce((sum, p) => sum + p.json.quality_score, 0) / allPosts.length;

// Group by source file
const bySource = {};
allPosts.forEach(post => {
  const source = post.json.source_file;
  if (!bySource[source]) {
    bySource[source] = { approved: 0, revision: 0, rejected: 0, total: 0 };
  }
  bySource[source].total++;
  if (post.json.status === 'APPROVED') bySource[source].approved++;
  if (post.json.status === 'NEEDS_REVISION') bySource[source].revision++;
  if (post.json.status === 'REJECTED') bySource[source].rejected++;
});

// Group by variation type
const byVariation = {};
allPosts.forEach(post => {
  const variation = post.json.variation;
  if (!byVariation[variation]) {
    byVariation[variation] = { approved: 0, revision: 0, rejected: 0, total: 0 };
  }
  byVariation[variation].total++;
  if (post.json.status === 'APPROVED') byVariation[variation].approved++;
  if (post.json.status === 'NEEDS_REVISION') byVariation[variation].revision++;
  if (post.json.status === 'REJECTED') byVariation[variation].rejected++;
});

// Common issues
const allIssues = {};
allPosts.forEach(post => {
  if (post.json.issues) {
    post.json.issues.forEach(issue => {
      allIssues[issue] = (allIssues[issue] || 0) + 1;
    });
  }
});

const topIssues = Object.entries(allIssues)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([issue, count]) => ({ issue, count }));

const batchDate = new Date().toISOString().split('T')[0];

return {
  json: {
    batch_id: `batch-${batchDate}`,
    generated_at: new Date().toISOString(),
    summary: {
      total_posts: allPosts.length,
      approved: approved.length,
      needs_revision: needsRevision.length,
      rejected: rejected.length,
      approval_rate: Math.round((approved.length / allPosts.length) * 100),
      avg_quality_score: Math.round(avgQualityScore)
    },
    by_source: bySource,
    by_variation: byVariation,
    top_issues: topIssues,
    approved_posts: approved.map(p => ({
      id: p.json.post_id,
      variation: p.json.variation,
      source: p.json.source_file,
      score: p.json.quality_score
    })),
    needs_attention: needsRevision.concat(rejected).map(p => ({
      id: p.json.post_id,
      variation: p.json.variation,
      source: p.json.source_file,
      status: p.json.status,
      score: p.json.quality_score,
      issues: p.json.issues
    }))
  }
};

