  .header h1 { margin: 0 0 10px 0; font-size: 28px; font-weight: 600; }
  .summary { display: flex; justify-content: space-around; padding: 20px; background: #f8f9fa; border-bottom: 2px solid #e9ecef; }
  .summary-item { text-align: center; }
  .summary-number { font-size: 36px; font-weight: bold; margin: 0; }
  .summary-number.approved { color: #28a745; }
  .summary-number.revision { color: #ffc107; }
  .summary-number.rejected { color: #dc3545; }
  .summary-label { font-size: 12px; color: #666; text-transform: uppercase; margin-top: 5px; }
  .content { padding: 30px; }
  .metric { background: #f8f9fa; padding: 15px; margin: 10px 0; border-left: 4px solid #667eea; border-radius: 4px; }
  .metric h3 { margin: 0 0 10px 0; color: #667eea; font-size: 16px; }
  .section-title { color: #667eea; font-size: 18px; font-weight: 600; margin: 20px 0 10px 0; border-bottom: 2px solid #667eea; padding-bottom: 5px; }
  .post-list { list-style: none; padding: 0; }
  .post-item { background: #f8f9fa; padding: 10px 15px; margin: 8px 0; border-radius: 5px; border-left: 4px solid #28a745; font-size: 14px; }
  .post-item.revision { border-left-color: #ffc107; }
  .post-item.rejected { border-left-color: #dc3545; }
  .issue-list { background: #fff3cd; border-left: 4px solid #ffc107; padding: 15px; margin: 15px 0; border-radius: 4px; }
  .issue-item { margin: 5px 0; font-size: 14px; }
  .footer { background: #f8f9fa; padding: 20px; text-align: center; color: #666; font-size: 12px; border-top: 1px solid #e9ecef; }
  .btn { display: inline-block; padding: 10px 20px; background: #667eea; color: white; text-decoration: none; border-radius: 5px; margin: 5px; font-size: 14px; }
  table { width: 100%; border-collapse: collapse; margin: 15px 0; font-size: 14px; }
  th, td { padding: 8px; text-align: left; border-bottom: 1px solid #ddd; }
  th { background: #f8f9fa; font-weight: 600; }
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <h1>🤖 Content Generation Complete</h1>
    <p>Batch ID: {{ $json.batch_id }}</p>
  </div>

  <div class="summary">
    <div class="summary-item">
      <div class="summary-number approved">{{ $json.summary.approved }}</div>
      <div class="summary-label">✅ Approved</div>
    </div>
    <div class="summary-item">
      <div class="summary-number revision">{{ $json.summary.needs_revision }}</div>
      <div class="summary-label">⚠️ Needs Revision</div>
    </div>
    <div class="summary-item">
      <div class="summary-number rejected">{{ $json.summary.rejected }}</div>
      <div class="summary-label">❌ Rejected</div>
    </div>
  </div>

  <div class="content">
    <div class="metric">
      <h3>📊 Overall Performance</h3>
      <p><strong>Total Posts Generated:</strong> {{ $json.summary.total_posts }}</p>
      <p><strong>Approval Rate:</strong> {{ $json.summary.approval_rate }}%</p>
      <p><strong>Average Quality Score:</strong> {{ $json.summary.avg_quality_score }}/100</p>
    </div>

    {{ $json.summary.approved > 0 ? '<h2 class="section-title">✅ Ready to Publish</h2><ul class="post-list">' + $json.approved_posts.map(post => '<li class="post-item"><strong>' + post.variation + '</strong> from ' + post.source + '<br><small>Score: ' + post.score + '/100 | ID: ' + post.id + '</small></li>').join('') + '</ul>' : '' }}

    <h2 class="section-title">📈 Performance by Variation</h2>
    <table>
      <thead>
        <tr>
          <th>Variation</th>
          <th>Approved</th>
          <th>Revision</th>
          <th>Rejected</th>
          <th>Total</th>
        </tr>
      </thead>
      <tbody>
        {{ Object.keys($json.by_variation).map(key => '<tr><td>' + key + '</td><td>' + $json.by_variation[key].approved + '</td><td>' + $json.by_variation[key].revision + '</td><td>' + $json.by_variation[key].rejected + '</td><td>' + $json.by_variation[key].total + '</td></tr>').join('') }}
      </tbody>
    </table>

    {{ $json.top_issues.length > 0 ? '<h2 class="section-title">⚠️ Top Issues to Address</h2><div class="issue-list">' + $json.top_issues.map(item => '<div class="issue-item">' + item.issue + ' (' + item.count + ' posts)</div>').join('') + '</div>' : '' }}

    {{ $json.needs_attention.length > 0 ? '<h2 class="section-title">🔧 Posts Needing Attention</h2><ul class="post-list">' + $json.needs_attention.slice(0, 10).map(post => '<li class="post-item ' + (post.status === 'REJECTED' ? 'rejected' : 'revision') + '"><strong>' + post.variation + '</strong> from ' + post.source + '<br><small>Status: ' + post.status + ' | Score: ' + post.score + '/100</small><br><small>Issues: ' + post.issues.join('; ') + '</small></li>').join('') + '</ul>' : '' }}

    <div style="text-align: center; margin: 30px 0;">
      <a href="file:///{{ process.cwd() }}/generated-posts/{{ $json.batch_id }}/" class="btn">📂 View All Generated Posts</a>
    </div>

    <div style="background: #e8f5e9; border-left: 4px solid #4caf50; padding: 15px; margin: 20px 0; border-radius: 4px;">
      <h3 style="color: #2e7d32; margin-top: 0;">📝 Next Steps</h3>
      <ol style="margin: 10px 0; padding-left: 20px; color: #1b5e20;">
        <li>Review approved posts in <code>generated-posts/{{ $json.batch_id }}/approved/</code></li>
        <li>Edit posts in <code>needs-revision/</code> folder</li>
        <li>Schedule approved posts using content calendar</li>
        <li>Track performance after publishing</li>
      </ol>
    </div>
  </div>

  <div class="footer">
    <p><strong>🤖 Terry Content Generator</strong> | AI-Whisperers</p>
    <p style="margin: 5px 0;">Powered by Claude 3.5 Sonnet • n8n Automation</p>
    <p style="margin: 10px 0 0 0; font-size: 11px; color: #999;">{{ $json.generated_at }}</p>
  </div>
</div>
</body>
</html>
